import messagebird
import json

# API endpoint to send WhatsApp/SMS notification via MessageBird (Bird.com)
# Called via: /api/method/send_whatsapp_notification
# Setup: bench --site college.bizaxl.local set-config messagebird_api_key "your_key"
recipient = frappe.form_dict.get("recipient")
message = frappe.form_dict.get("message")
channel = frappe.form_dict.get("channel", "sms")

# API token check
api_token = frappe.form_dict.get("api_token")
expected_token = frappe.conf.get("college_app_api_token")
if not api_token or not expected_token or api_token != expected_token:
    frappe.response["message"] = {"error": "Invalid API token"}
elif not recipient or not message:
    frappe.response["message"] = {"error": "recipient and message are required"}
else:
    try:
        client = messagebird.Client(frappe.conf.get("messagebird_api_key"))
        msg = client.message_create("CollegeERP", recipient, message)
        frappe.response["message"] = {"status": "sent", "recipient": recipient, "channel": channel}
    except Exception as e:
        frappe.response["message"] = {"error": str(e)[:300]}
